/* TIMEABI: target-side tests for the R11F calendar and wall clock.
 *
 * Expected values come from timeabi_vectors.h, generated by gen_vectors.py from
 * Python datetime and the host C library (independent of this SDK).
 *
 * Build mode (set by the build, see docs/R11F-FIXED-CLOCK.md):
 *   TIMEABI_MODE 0  no clock configured (the regression image): time is unavailable.
 *   TIMEABI_MODE 1  pinned clock at TIMEABI_EPOCH: time is fixed.
 *   TIMEABI_MODE 2  advancing clock from TIMEABI_EPOCH: time follows the timer.
 * TIMEABI_RATE_NUM / TIMEABI_RATE_DEN: the timer rate in ticks per second.
 */
#include <stdio.h>
#include <string.h>
#include <time.h>
#include "qdos386.h"
#include "../check.h"
#include "timeabi_vectors.h"

#ifndef TIMEABI_MODE
#define TIMEABI_MODE 0
#endif
#ifndef TIMEABI_EPOCH
#define TIMEABI_EPOCH 0UL
#endif
#ifndef TIMEABI_RATE_NUM
#define TIMEABI_RATE_NUM 1193182UL
#endif
#ifndef TIMEABI_RATE_DEN
#define TIMEABI_RATE_DEN 11932UL
#endif

static int same_tm(const struct tm *a, const struct qd_tmf *f)
{
	return a->tm_sec == f->sec && a->tm_min == f->min && a->tm_hour == f->hour
	    && a->tm_mday == f->mday && a->tm_mon == f->mon && a->tm_year == f->year
	    && a->tm_wday == f->wday && a->tm_yday == f->yday && a->tm_isdst == 0;
}

static void fill_tm(struct tm *tm, int sec, int min, int hour, int mday, int mon, int year)
{
	memset(tm, 0, sizeof *tm);
	tm->tm_sec = sec;
	tm->tm_min = min;
	tm->tm_hour = hour;
	tm->tm_mday = mday;
	tm->tm_mon = mon;
	tm->tm_year = year;
}

/* ---- calendar checks: the same on every image ----------------------------- */

static void calendar_gmtime(void)
{
	int i, bad_gm = 0, bad_lt = 0, bad_rt = 0, first = -1, n;
	struct tm g;
	time_t t;

	n = (int) (sizeof qd_vec_gm / sizeof qd_vec_gm[0]);
	for (i = 0; i < n; i++) {
		t = (time_t) qd_vec_gm[i].t;
		memcpy(&g, gmtime(&t), sizeof g);
		if (!same_tm(&g, &qd_vec_gm[i].f)) {
			bad_gm++;
			if (first < 0) first = i;
		}
		memcpy(&g, localtime(&t), sizeof g);
		if (!same_tm(&g, &qd_vec_gm[i].f))
			bad_lt++;
		/* round trip: mktime of the broken-down time is the original time */
		g = *gmtime(&t);
		if (mktime(&g) != t)
			bad_rt++;
	}
	if (bad_gm)
		printf("  first gmtime mismatch at vector %d (t=%lu)\n", first, qd_vec_gm[first].t);
	CHECK("gmtime fields match the reference for all vectors", bad_gm == 0);
	CHECK("localtime is UTC: same fields as gmtime for all vectors", bad_lt == 0);
	CHECK("mktime(gmtime(t)) == t for all vectors", bad_rt == 0);
	CHECK("gmtime(NULL) is NULL", gmtime(NULL) == NULL);
	t = (time_t) 0xFFFFFFFFUL;
	CHECK("gmtime(0xFFFFFFFF) is NULL (the sentinel is not a time)", gmtime(&t) == NULL);
	CHECK("localtime(0xFFFFFFFF) is NULL", localtime(&t) == NULL);
	CHECK("ctime(0xFFFFFFFF) is NULL", ctime(&t) == NULL);
	t = (time_t) 4294967294UL;
	CHECK("gmtime(TMAX) gives 2106-02-07 06:28:14", gmtime(&t) != NULL && gmtime(&t)->tm_year == 206
	      && gmtime(&t)->tm_mday == 7 && gmtime(&t)->tm_hour == 6 && gmtime(&t)->tm_sec == 14);
	CHECK("localtime(NULL) is NULL", localtime(NULL) == NULL);
}

static void calendar_mktime(void)
{
	int i, n, bad = 0, bad_norm = 0, first = -1;
	struct tm tm;
	time_t r;

	n = (int) (sizeof qd_vec_mk / sizeof qd_vec_mk[0]);
	for (i = 0; i < n; i++) {
		const struct qd_vec_mk *v = &qd_vec_mk[i];
		fill_tm(&tm, v->sec, v->min, v->hour, v->mday, v->mon, v->year);
		r = mktime(&tm);
		if ((unsigned long) r != v->expect) {
			bad++;
			if (first < 0) first = i;
			continue;
		}
		if (v->has_norm && !same_tm(&tm, &v->norm))
			bad_norm++;
	}
	if (bad)
		printf("  first mktime mismatch at vector %d (expected %lu)\n", first,
		       qd_vec_mk[first].expect);
	CHECK("mktime result matches the reference for all vectors (incl. -1 cases)", bad == 0);
	CHECK("mktime normalizes wday, yday, month and day fields", bad_norm == 0);
	CHECK("mktime(NULL) is -1", mktime(NULL) == (time_t) -1);
	CHECK("mktime rejects 1969-12-31 23:59:59", (fill_tm(&tm, 59, 59, 23, 31, 11, 69),
	      mktime(&tm) == (time_t) -1));
	CHECK("mktime accepts 2106-02-07 06:28:14 (the maximum)", (fill_tm(&tm, 14, 28, 6, 7, 1, 206),
	      mktime(&tm) == (time_t) 4294967294UL));
	CHECK("mktime rejects one second past the maximum", (fill_tm(&tm, 15, 28, 6, 7, 1, 206),
	      mktime(&tm) == (time_t) -1));
	CHECK("mktime leaves its struct unchanged on failure",
	      (fill_tm(&tm, 0, 0, 0, 1, 0, 0), mktime(&tm), tm.tm_year == 0 && tm.tm_mday == 1));
}

static void calendar_strftime(void)
{
	int i, n, bad = 0, bad_exact = 0, bad_short = 0, first = -1, len;
	char buf[128];
	struct tm tm;
	time_t t;
	size_t got;

	n = (int) (sizeof qd_vec_sf / sizeof qd_vec_sf[0]);
	for (i = 0; i < n; i++) {
		const struct qd_vec_sf *v = &qd_vec_sf[i];
		t = (time_t) v->t;
		tm = *gmtime(&t);
		memset(buf, 'x', sizeof buf);
		got = strftime(buf, sizeof buf, v->fmt, &tm);
		len = (int) strlen(v->expect);
		if (strcmp(buf, v->expect) != 0 || (int) got != len) {
			bad++;
			if (first < 0) first = i;
		}
		if (len > 0) {
			/* exact size: len + 1 bytes is enough; len bytes is not */
			got = strftime(buf, (size_t) len + 1, v->fmt, &tm);
			if ((int) got != len || strcmp(buf, v->expect) != 0)
				bad_exact++;
			got = strftime(buf, (size_t) len, v->fmt, &tm);
			if (got != 0 || buf[0] != '\0')
				bad_short++;
		}
	}
	if (bad)
		printf("  first strftime mismatch at vector %d (format \"%s\")\n", first,
		       qd_vec_sf[first].fmt);
	CHECK("strftime output matches the reference for all vectors", bad == 0);
	CHECK("strftime exact-size buffer (len+1) succeeds", bad_exact == 0);
	CHECK("strftime insufficient buffer (len) returns 0 and empties s", bad_short == 0);

	t = 0;
	tm = *gmtime(&t);
	CHECK("strftime with max 0 returns 0", strftime(buf, 0, "%Y", &tm) == 0);
	CHECK("strftime unknown conversion returns 0", strftime(buf, sizeof buf, "%Q", &tm) == 0);
	CHECK("strftime trailing lone % returns 0", strftime(buf, sizeof buf, "abc%", &tm) == 0);
	CHECK("strftime %Z is UTC", (strftime(buf, sizeof buf, "%Z", &tm) == 3 && strcmp(buf, "UTC") == 0));
	CHECK("strftime %% is a percent sign", (strftime(buf, sizeof buf, "%%", &tm) == 1 && buf[0] == '%'));
}

static void calendar_asctime(void)
{
	int i, n, bad = 0, bad_ct = 0, first = -1;
	struct tm tm;
	time_t t;

	n = (int) (sizeof qd_vec_as / sizeof qd_vec_as[0]);
	for (i = 0; i < n; i++) {
		t = (time_t) qd_vec_as[i].t;
		tm = *gmtime(&t);
		if (strcmp(asctime(&tm), qd_vec_as[i].expect) != 0) {
			bad++;
			if (first < 0) first = i;
		}
		if (strcmp(ctime(&t), qd_vec_as[i].expect) != 0)
			bad_ct++;
	}
	if (bad)
		printf("  first asctime mismatch at vector %d\n", first);
	CHECK("asctime output matches the reference for all vectors", bad == 0);
	CHECK("ctime(t) equals the reference for all vectors", bad_ct == 0);
	CHECK("ctime(NULL) is NULL", ctime(NULL) == NULL);
}

static void calendar_misc(void)
{
	CHECK("difftime(10, 4) == 6", difftime((time_t) 10, (time_t) 4) == 6.0);
	CHECK("difftime(4, 10) == -6", difftime((time_t) 4, (time_t) 10) == -6.0);
	CHECK("clock() is explicitly unavailable", clock() == (clock_t) -1);
	CHECK("CLOCKS_PER_SEC is the nominal 1000", CLOCKS_PER_SEC == 1000);
}

/* ---- wall clock checks: depend on the build mode ----------------------- */

/* Expected whole seconds after T ticks: floor(T * den / num).  T is kept below
 * 180000 so that T * den fits 32 bits (den = 11932). */
static unsigned long secs_for_ticks(unsigned long T)
{
	return (T * TIMEABI_RATE_DEN) / TIMEABI_RATE_NUM;
}

static void clock_none(void)
{
	time_t v = 0;
	time_t t;
	unsigned long w = qd_wall_time();

	CHECK("no clock: qd_wall_time reports unavailable", w == 0xFFFFFFFFUL);
	CHECK("no clock: time(NULL) is -1", time(NULL) == (time_t) -1);
	CHECK("no clock: time(&v) is -1 and sets v", (time(&v) == (time_t) -1 && v == (time_t) -1));
	t = 86400;
	CHECK("no clock: gmtime still works from supplied values", gmtime(&t)->tm_mday == 2);
}

static void clock_pinned(void)
{
	time_t v = 0;
	time_t t;
	unsigned long w0, w1;
	char *s;

	w0 = qd_wall_time();
	CHECK("pinned clock: qd_wall_time is the configured epoch", w0 == TIMEABI_EPOCH);
	qd_yield(300);                       /* about 3 seconds of ticks */
	w1 = qd_wall_time();
	CHECK("pinned clock: time does not advance over 300 ticks", w1 == TIMEABI_EPOCH);
	CHECK("pinned clock: time(NULL) is the epoch", time(NULL) == (time_t) TIMEABI_EPOCH);
	CHECK("pinned clock: time(&v) sets v to the epoch", (time(&v) == (time_t) TIMEABI_EPOCH
	      && v == (time_t) TIMEABI_EPOCH));
	t = (time_t) TIMEABI_EPOCH;
	s = ctime(&t);
	CHECK("pinned clock: ctime of the epoch is consistent with gmtime",
	      s != NULL && strlen(s) == 25);
}

static void clock_advance(void)
{
	unsigned long T1, T2, w, w0, dw;
	unsigned long lo, hi;
	time_t v;

	T1 = qd_ticks();
	w0 = qd_wall_time();
	T2 = qd_ticks();
	CHECK("advancing clock: starts at the configured epoch, bracketed by ticks",
	      w0 >= TIMEABI_EPOCH && w0 - TIMEABI_EPOCH >= secs_for_ticks(T1)
	      && w0 - TIMEABI_EPOCH <= secs_for_ticks(T2));
	qd_yield(500);                       /* about 5 seconds */
	T1 = qd_ticks();
	w = qd_wall_time();
	T2 = qd_ticks();
	/* wall - epoch must equal the seconds of the ticks the clock has counted.
	 * The clock counts the same ticks as qd_ticks, so the reading is bracketed
	 * by the tick counts read immediately before and after it. */
	lo = secs_for_ticks(T1);
	hi = secs_for_ticks(T2);
	dw = w - TIMEABI_EPOCH;
	CHECK("advancing clock: wall minus epoch matches the tick count (bracketed)",
	      w != 0xFFFFFFFFUL && dw >= lo && dw <= hi);
	CHECK("advancing clock: about 5 seconds elapse over 500 ticks", dw >= 4);
	v = time(NULL);
	CHECK("advancing clock: time(NULL) agrees with qd_wall_time",
	      (unsigned long) v >= w && (unsigned long) v <= w + 1);
}

int main(void)
{
	printf("TIMEABI: mode %d, epoch %lu, rate %lu/%lu\n", TIMEABI_MODE,
	       (unsigned long) TIMEABI_EPOCH, (unsigned long) TIMEABI_RATE_NUM,
	       (unsigned long) TIMEABI_RATE_DEN);

	calendar_gmtime();
	calendar_mktime();
	calendar_strftime();
	calendar_asctime();
	calendar_misc();

	if (TIMEABI_MODE == 0)
		clock_none();
	else if (TIMEABI_MODE == 1)
		clock_pinned();
	else
		clock_advance();

	return finish("TIMEABI");
}
